mapper.update:
update batch.batch_day_catchup_operation
set operation_status = #{nextStatus}, items_json = cast(#{itemsJson} as jsonb),
    revision = revision + 1, updated_at = current_timestamp
where tenant_id = #{tenantId}
  and request_key_hash = #{requestKeyHash}
  and revision = #{expectedRevision}
  and operation_status = #{expectedStatus}
  and (
      (operation_status = 'PREPARED' and #{nextStatus} in ('RUNNING', 'COMPLETE'))
      or (operation_status = 'RUNNING' and #{nextStatus} in ('RUNNING', 'COMPLETE', 'UNKNOWN'))
      or (operation_status = 'UNKNOWN' and #{nextStatus} in ('UNKNOWN', 'COMPLETE'))
  )

update batch.batch_day_catchup_operation
set operation_status = #{nextStatus}, items_json = cast(#{itemsJson} as jsonb),
    revision = revision + 1, updated_at = current_timestamp
where tenant_id = #{tenantId}
  and request_key_hash = #{requestKeyHash}
  and revision = #{expectedRevision}
  and operation_status = 'UNKNOWN'
